shotmap = {Path(s['file']).name:s for s in shots}

def picture(file, caption='', phone=True):
    s = shotmap[file]
    w, h = s['pixels']
    title, size, url = s['title'], s['viewport'], s['source']
    return f'''<figure class="evidence {'phone' if phone else 'wide'}"><button class="zoom" data-image="assets/{file}" data-caption="{E(title)} · {size} · 11 أكتوبر 2026" aria-label="تكبير صورة {E(title)}"><img src="assets/{file}" width="{w}" height="{h}" alt="{E(title)}" loading="lazy"></button><figcaption><strong>{E(title)}</strong><span>{size} · 11 أكتوبر 2026</span><p>{caption}</p><a href="{url}" target="_blank" rel="noopener">افتح الصفحة الأصلية في المتجر</a></figcaption></figure>'''

