    parts.append(f'''<article class="finding" id="{f['id']}" data-number="{number}" data-priority="{f['priority']}"><div class="finding-top"><span class="tag priority-{f['priority']}">{priority}</span><a class="finding-id" href="#{f['id']}">ملاحظة {number}</a><span>{f['stage']}</span></div><h3>{f['title']}</h3><p class="device-label">فُحص على {f['device']} · التعديل {effort}؛ يقدّر الفريق وقته بعد المراجعة.</p><div class="finding-grid"><div><h4>ماذا لاحظنا؟</h4><p>{f['observation']}</p><h4>كيف قد يربك العميلة؟</h4><p>{f['impact']}</p></div><div class="recommendation"><h4>ما الذي نعدّله؟</h4><p>{f['recommendation']}</p><h4>كيف نتأكد بعد التعديل؟</h4><p>{f['acceptance']}</p></div></div><div class="evidence-links"><span>شاهد الصور</span>{links}</div></article>''')
