parts.append('''<div class="table-wrap"><table><caption>المشكلة وما يمكن تعديله على كل جهاز</caption><thead><tr><th>المكان</th><th>على الموبايل</th><th>على الكمبيوتر</th><th>ماذا نعدّل؟</th></tr></thead><tbody><tr><td>الصورة الرئيسية</td><td>الكلام صغير لأن الصورة تصغر</td><td>الصورة طويلة وتؤخر ظهور الأقسام</td><td>صورة مناسبة لكل شاشة مع كلام وزر واضحين</td></tr><tr><td>أقسام المتجر</td><td>تحتاج فتح القائمة ثم أقسام داخلية</td><td>الأقسام مخفية داخل زر القائمة رغم وجود مساحة</td><td>تبسيط القائمة، وإظهار الأقسام أعلى الصفحة على الكمبيوتر</td></tr><tr><td>صفحة المنتج</td><td>صورة طويلة وزر شراء يبقى أسفل الشاشة</td><td>الصورة والمعلومات بجانب بعضهما</td><td>الإبقاء على سهولة الوصول لزر الشراء، وإظهار الخامة والمقاس</td></tr><tr><td>رسائل الشراء</td><td>تغطي جزءًا كبيرًا من الشاشة</td><td>تغطي بعض معلومات المنتج والأزرار</td><td>إيقافها في المنتج والسلة وإتمام الطلب</td></tr><tr><td>واتساب</td><td>يغطي جزءًا من زر الشراء</td><td>أقل تغطية للأزرار في الصورة التي فحصناها</td><td>زر واحد بعيد عن أزرار الشراء</td></tr><tr><td>السلة وإتمام الطلب</td><td>فحصنا حتى نموذج الشراء دون حساب</td><td>لم نفحص هذه الخطوات كاملة بشكل مستقل</td><td>تجربتها أيضًا على الكمبيوتر بعد التعديل</td></tr></tbody></table></div>''')
